// core: sliding window averages over a temperature stream
const stream=[22.1,22.4,22.2,23.0,24.5,25.1,24.9,23.2,22.8,22.5];const w=4;const avgs=[];
for(let i=0;i+w<=stream.length;i++){const seg=stream.slice(i,i+w);avgs.push(+(seg.reduce((a,b)=>a+b,0)/w).toFixed(2));}
const peak=avgs.indexOf(Math.max(...avgs));
J({windows:avgs.length,averages:avgs,peak_window:peak,peak_value:Math.max(...avgs)});assert(avgs.length===7,'windows');assert(Math.max(...avgs)>24,'peak');

// end-to-end: raw readings -> 1-min windows -> threshold alerts -> summary
const readings=[];for(let m=0;m<60;m++)readings.push(20+Math.sin(m/6)*2+(m>40?3:0));
const wins=[];for(let i=0;i<60;i+=10){const seg=readings.slice(i,i+10);wins.push(seg.reduce((a,b)=>a+b,0)/10);}
const alerts=wins.map((v,i)=>({window:i,avg:+v.toFixed(2),alert:v>22.5}));const nAlerts=alerts.filter(a=>a.alert).length;
J({windows:wins.length,alerts:nAlerts,summary_ratio:(60/6)});assert(wins.length===6,'win count');assert(nAlerts>=1,'alerts');
